    ? pointer.manifestUrls
    : (pointer?.manifestUrl ? { [pointer.scenario || "mean"]: pointer.manifestUrl } : {});
  if (pointer?.status !== "complete" || !Object.keys(manifestUrls).length) {
    throw new Error("The physics forecast pointer is not complete.");
  }
